export function initBulkPrices(){
const root=document.getElementById('bulk-prices-root');
if(!root||root.dataset.bulkReady)return false;
{

const key='colafix-bulk-prices-v1',money=v=>'R$ '+Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;try{data=JSON.parse(localStorage.getItem(key))}catch{}if(!data||!Array.isArray(data.quotes)||!Array.isArray(data.contracts))data={quotes:[],contracts:[]};
let tab='prices',range=6,monthlyOrders={},monthlyError='';
async function loadMonthly(){try{const response=await fetch('/api/cement',{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);const json=await response.json();monthlyOrders=json.monthlyOrders||{};monthlyError='';}catch(e){monthlyError='Falha ao consultar pedidos: '+e.message}draw()}

const save=()=>localStorage.setItem(key,JSON.stringify(data));
const latest=s=>rows().find(q=>q.supplier===s);
const rows=()=>[...data.quotes].sort((a,b)=>b.date.localeCompare(a.date));
const table=(heads,body)=>'<div class="bulk-scroll"><table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div>';
const chart=()=>{const days=[...new Set(rows().map(q=>q.date))].sort().slice(-range).reverse(),names=['Votorantim','Intercement'];if(!days.length)return '<p>Cadastre cotações para visualizar o gráfico.</p>';const vals=data.quotes.filter(q=>days.includes(q.date)).map(q=>Number(q.price)),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1;return '<svg viewBox="0 0 600 170" width="100%" height="190" role="img" aria-label="Evolução dos preços">'+names.map((s,k)=>{const pts=days.map((d,i)=>{const q=rows().find(x=>x.supplier===s&&x.date===d);return q?[30+i*540/Math.max(1,days.length-1),145-(Number(q.price)-min)/span*110]:null}).filter(Boolean);return '<polyline fill="none" stroke="'+(k?'#ef4444':'#1683f6')+'" stroke-width="3" points="'+pts.map(p=>p.join(',')).join(' ')+'"/>'+pts.map(p=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="4" fill="'+(k?'#ef4444':'#1683f6')+'"/>').join('')}).join('')+'</svg><div>🔵 Votorantim &nbsp; 🔴 InterCement</div>'};
function draw(){const v=latest('Votorantim'),i=latest('Intercement');const q=(s,x)=>{const isV=s==='Votorantim',history=rows().filter(r=>r.supplier===s),previous=history[1],change=x&&previous&&Number(previous.price)?((Number(x.price)-Number(previous.price))/Number(previous.price))*100:null;const series=history.slice(0,7).reverse(),prices=series.map(r=>Number(r.price)),low=Math.min(...prices),high=Math.max(...prices),spread=high-low||1;const coords=prices.map((p,i)=>[5+i*145/Math.max(1,prices.length-1),40-(p-low)/spread*30]);const spark=coords.length>1?'<svg class="bulk-spark" viewBox="0 0 160 48" aria-label="Evolução recente de preço"><polyline fill="none" stroke="'+(isV?'#1683ed':'#ef333c')+'" stroke-width="2.5" stroke-linejoin="round" points="'+coords.map(p=>p.join(',')).join(' ')+'"/>'+coords.map(p=>'<circle r="2.5" cx="'+p[0]+'" cy="'+p[1]+'" fill="'+(isV?'#1683ed':'#ef333c')+'"/>').join('')+'</svg>':'<div class="bulk-spark-empty">Histórico após novas cotações</div>';const sign=change===null?'—':(change>0?'↑ ':'↓ ')+Math.abs(change).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%';return '<article class="bulk-panel bulk-price-card '+(isV?'bulk-card-v':'bulk-card-i')+'"><div class="bulk-price-top">'+(isV?'<img class="bulk-official-logo" src="https://commons.wikimedia.org/wiki/Special:Redirect/file/Logotipo_da_Votorantim_Cimentos.svg" alt="Votorantim Cimentos">':'<div class="bulk-inter-logo"><i aria-hidden="true"></i><span>InterCement</span></div>')+'<div class="bulk-price-current"><small>Preço atual (R$/t)</small><strong>'+(x?money(x.price):'Não cadastrado')+'</strong></div></div><div class="bulk-price-bottom"><div class="bulk-price-change '+(change===null?'neutral':change<=0?'down':'up')+'"><strong>'+sign+'</strong><small>'+(change===null?'Aguardando histórico':'em relação ao mês anterior')+'</small></div>'+spark+'</div></article>'};root.innerHTML='<div class="bulk-head"><h2>Cimento a Granel</h2><small>Preços, contratos vigentes e histórico de cotações.</small></div><div class="bulk-tabs"><button data-bulk-tab="prices" '+(tab==='prices'?'class="active"':'')+'>Preços</button><button data-bulk-tab="contracts" '+(tab==='contracts'?'class="active"':'')+'>Contratos Votorantim</button><button data-bulk-tab="history" '+(tab==='history'?'class="active"':'')+'>Histórico</button></div>'+
(tab==='prices'?'<div class="bulk-grid">'+q('Votorantim',v)+q('Intercement',i)+'<article class="bulk-panel"><h3>📊 Comparativo rápido (R$/t)</h3>'+table(['Fornecedor','Preço atual'],[['Votorantim',v],['InterCement',i]].map(([s,x])=>'<tr><td>'+s+'</td><td>'+(x?money(x.price):'—')+'</td></tr>').join('')+'<tr><th>Diferença</th><th>'+(v&&i?money(Math.abs(v.price-i.price)):'—')+'</th></tr>')+'</article></div><div class="bulk-grid bulk-grid-two"><article class="bulk-panel"><h3>📈 Evolução dos preços</h3>'+chart()+'</article><article class="bulk-panel"><h3>Últimas cotações</h3>'+table(['Data','Fornecedor','Preço'],rows().slice(0,8).map(x=>'<tr><td>'+esc(x.date)+'</td><td>'+esc(x.supplier)+'</td><td>'+money(x.price)+'</td></tr>').join(''))+'</article></div><div class="bulk-panel"><h3>Nova cotação</h3><form id="bulk-quote-form" class="bulk-form"><select name="supplier"><option>Votorantim</option><option>Intercement</option></select><input name="date" type="date" required value="'+new Date().toISOString().slice(0,10)+'"><input name="price" type="number" min="0.01" step="0.01" placeholder="Preço por tonelada" required><button>Salvar cotação</button></form></div>':
tab==='contracts'?'<div class="bulk-panel"><h3>Contratos vigentes — Votorantim</h3>'+table(['Contrato','Produto','Início','Fim','Preço (R$/t)','Situação'],data.contracts.map(x=>'<tr><td>'+esc(x.number)+'</td><td>'+esc(x.product)+'</td><td>'+esc(x.start)+'</td><td>'+esc(x.end)+'</td><td>'+money(x.price)+'</td><td>'+(x.end>=new Date().toISOString().slice(0,10)?'Vigente':'Encerrado')+'</td></tr>').join(''))+'<h3>Novo contrato</h3><form id="bulk-contract-form" class="bulk-form"><input name="number" placeholder="Nº contrato" required><input name="product" placeholder="Produto" required><input name="start" type="date" required><input name="end" type="date" required><input name="price" type="number" step="0.01" min="0" placeholder="Preço R$/t" required><button>Salvar contrato</button></form></div><div class="bulk-panel"><h3>Pedidos do sistema por mês</h3><p>Cadastre o pedido interno separado do contrato, para preenchimento automático no agendamento.</p><form id="bulk-monthly-form" class="bulk-form"><label>Mês <input type="month" name="month" required value="'+new Date().toISOString().slice(0,7)+'"></label><label>Empresa <select name="company"><option>Colafix</option></select></label><label>Fornecedor <select name="supplier"><option>Votorantim</option><option>Intercement</option></select></label><label>Pedido do sistema <input name="systemOrder" required placeholder="Nº pedido interno"></label><button>Salvar pedido</button></form><p id="bulk-monthly-message">'+esc(monthlyError)+'</p>'+table(['Mês','Fornecedor','Pedido do sistema'],Object.entries(monthlyOrders).flatMap(([month,values])=>Object.entries(values).filter(([supplier,order])=>order).map(([supplier,order])=>'<tr><td>'+esc(month)+'</td><td>'+esc(supplier)+'</td><td>'+esc(order)+'</td></tr>')).join(''))+'</div>':
'<div class="bulk-panel"><h3>Histórico de preços</h3><div class="bulk-tabs">'+[3,6,12].map(n=>'<button data-range="'+n+'" '+(range===n?'class="active"':'')+'>'+n+'M</button>').join('')+'</div>'+chart()+table(['Data','Fornecedor','Preço (R$/t)'],rows().map(x=>'<tr><td>'+esc(x.date)+'</td><td>'+esc(x.supplier)+'</td><td>'+money(x.price)+'</td></tr>').join(''))+'</div>');
root.querySelectorAll('[data-bulk-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.bulkTab;draw()});root.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{range=Number(b.dataset.range);draw()});
const qf=root.querySelector('#bulk-quote-form');if(qf)qf.onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(qf));data.quotes=data.quotes.filter(x=>!(x.date===o.date&&x.supplier===o.supplier));data.quotes.push({...o,price:Number(o.price)});save();draw()};
const mf=root.querySelector('#bulk-monthly-form');if(mf){const fill=()=>mf.elements.systemOrder.value=monthlyOrders[mf.elements.month.value]?.[mf.elements.supplier.value]||'';mf.elements.month.onchange=fill;mf.elements.supplier.onchange=fill;fill();mf.onsubmit=async e=>{e.preventDefault();const msg=root.querySelector('#bulk-monthly-message');msg.textContent='Salvando...';try{const o=Object.fromEntries(new FormData(mf));const response=await fetch('/api/cement-monthly-order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({month:o.month,supplier:o.supplier,systemOrder:o.systemOrder})});const j=await response.json();if(!response.ok)throw Error(j.error||'Erro ao salvar');monthlyOrders[o.month]??={};monthlyOrders[o.month][o.supplier]=o.systemOrder;draw();root.querySelector('#bulk-monthly-message').textContent='Pedido salvo e disponível para agendamento.';}catch(error){msg.textContent=error.message}}};const cf=root.querySelector('#bulk-contract-form');if(cf)cf.onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(cf));data.contracts.push({...o,price:Number(o.price)});save();draw()};}
draw();loadMonthly();}
root.dataset.bulkReady='1';
return true;
}
function bootBulkPrices(){try{return initBulkPrices()}catch(error){const el=document.getElementById('bulk-prices-root');if(el)el.innerHTML='<div class="bulk-panel"><strong>Falha ao carregar o painel:</strong> '+String(error.message).replace(/[<>]/g,'')+'</div>';console.error('Cimento a granel:',error);return false}}
if(!bootBulkPrices()){
 const observer=new MutationObserver(()=>{if(bootBulkPrices())observer.disconnect()});
 observer.observe(document.body,{childList:true,subtree:true});
 document.addEventListener('DOMContentLoaded',()=>{if(bootBulkPrices())observer.disconnect()},{once:true});
}
document.addEventListener('click',e=>{if(e.target.closest('[data-tab="bulkprices"]'))setTimeout(bootBulkPrices,0)},true);
